        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(i, None)
        return coords[i] if 0 <= i < len(coords) else None

    def d(i, j):
        if dist is not None:
            return dist[i][j]
        ci = coord(i)
        cj = coord(j)
        if ci is None or cj is None:
            return 0
        dx = ci[0] - cj[0]
        dy = ci[1] - cj[1]
        return (dx * dx + dy * dy) ** 0.5

    customers.sort(key=lambda c: (-demand(c), d(depot, c), c))

    routes = []
    unrouted = customers[:]
    while unrouted:
        route = [unrouted.pop(0)]
        load = demand(route[0])
        while unrouted:
            best = None
            best_idx = -1
            best_side = 0
            left = route[0]
            right = route[-1]
            for idx, c in enumerate(unrouted):
                dc = demand(c)
                if load + dc > capacity:
                    continue
                cl = d(c, left) - d(depot, c)
                cr = d(right, c) - d(depot, c)
                if best is None or cl < best or (cl == best and c < unrouted[best_idx]):
                    best = cl
                    best_idx = idx
                    best_side = 0
                if cr < best or (cr == best and c < unrouted[best_idx]):
                    best = cr
                    best_idx = idx
                    best_side = 1
            if best_idx < 0:
                break
            c = unrouted.pop(best_idx)
            if best_side == 0:
                route.insert(0, c)
            else:
                route.append(c)
            load += demand(c)
        routes.append(route)

    def rload(r):
        s = 0
        for c in r:
            s += demand(c)
        return s

    def rcost(r):
        if not r:
            return 0
        t = d(depot, r[0])
        for i in range(len(r) - 1):
            t += d(r[i], r[i + 1])
        return t + d(r[-1], depot)

    improved = True
    while improved:
        improved = False
        for a in range(len(routes)):
            if improved:
                break
            ra = routes[a]
            for i in range(len(ra)):
                c = ra[i]
                dc = demand(c)
                for b in range(len(routes)):
                    rb = routes[b]
                    if a == b:
                        if len(ra) <= 1:
                            continue
                        for pos in range(len(ra) + 1):
                            if pos == i or pos == i + 1:
                                continue
                            nr = ra[:]
                            x = nr.pop(i)
                            ins = pos - 1 if pos > i else pos
                            nr.insert(ins, x)
                            if rcost(nr) + 1e-12 < rcost(ra):
                                routes[a] = nr
                                improved = True
                                break
                        if improved:
                            break
                    else:
                        if rload(rb) + dc > capacity:
                            continue
                        for pos in range(len(rb) + 1):
                            nra = ra[:]
                            nrb = rb[:]
                            x = nra.pop(i)
                            nrb.insert(pos, x)
                            if rcost(nra) + rcost(nrb) + 1e-12 < rcost(ra) + rcost(rb):
                                routes[a] = nra
                                routes[b] = nrb
                                improved = True
                                break
                        if improved:
                            break
                if improved:
                    break
        if improved:
            continue
        for a in range(len(routes)):
            if improved:
                break
            ra = routes[a]
            for b in range(a + 1, len(routes)):
                rb = routes[b]
                la = rload(ra)
                lb = rload(rb)
                for i in range(len(ra)):
                    ca = ra[i]
                    da = demand(ca)
                    for j in range(len(rb)):
                        cb = rb[j]
                        db = demand(cb)
                        if la - da + db > capacity or lb - db + da > capacity:
                            continue
                        nra = ra[:]
                        nrb = rb[:]
                        nra[i] = cb
                        nrb[j] = ca
                        if rcost(nra) + rcost(nrb) + 1e-12 < rcost(ra) + rcost(rb):
                            routes[a] = nra
                            routes[b] = nrb
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1
    missing = [c for c in customers if seen.get(c, 0) == 0]
    if missing or any(v != 1 for v in seen.values()):
        kept = []
        used = {}
        for r in routes:
            nr = []
            for c in r:
                if used.get(c, 0) == 0:
                    nr.append(c)
                    used[c] = 1
            if nr:
                kept.append(nr)
        routes = kept
        for c in missing:
            placed = False
            dc = demand(c)
            best_r = -1
            best_p = 0
            best_delta = None
            for ri, r in enumerate(routes):
                if rload(r) + dc > capacity:
                    continue
                for p in range(len(r) + 1):
                    a = depot if p == 0 else r[p - 1]
                    b = depot if p == len(r) else r[p]
                    delta = d(a, c) + d(c, b) - d(a, b)
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_r = ri
                        best_p = p
            if best_r < 0:
                routes.append([c])
            else:
                routes[best_r].insert(best_p, c)

    routes = [r for r in routes if r]
    return routes
